public int DigitalRootRecursive(int n)
{
    if (n < 10) return n;
    int sum = 0;
    while (n > 0)
    {
        sum += n % 10;
        n /= 10;
    }
    return DigitalRootRecursive(sum);
}

public int DigitalRootIterative(int n)
{
    while (n >= 10)
    {
        int sum = 0;
        while (n > 0)
        {
            sum += n % 10;
            n /= 10;
        }
        n = sum;
    }
    return n;
}

public int DigitalRootMath(int n)
{
    if (n == 0) return 0;
    return 1 + (n - 1) % 9;
}
